class Runner:
    """Records calls; raises RuntimeError for names in fail_on."""
    def __init__(self, fail_on=()):
        self.fail_on = set(fail_on)
        self.calls = []

    def __call__(self, name):
        self.calls.append(name)
        if name in self.fail_on:
            raise RuntimeError("boom: %s" % name)
        return "return value discarded"


def make(edges):
    s = Scheduler()
    for t, d in edges:
        s.add_dependency(t, d)
    return s


